1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir>
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
9	//
10	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
11	
12	import {
13	  createHash,
14	  createPrivateKey,
15	  createPublicKey,
16	  generateKeyPairSync,
17	  sign as cryptoSign,
18	  verify as cryptoVerify,
19	} from 'node:crypto';
20	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
21	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
22	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	
25	export const PROOF_VERSION = '1.0';
26	// 启用多方共签时证明版本升为 1.1；共签清单（proof/sbom.cosignatures.json）的 schemaVersion。
27	export const PROOF_VERSION_COSIGN = '1.1';
28	export const COSIGN_SCHEMA_VERSION = '1.0';
29	
30	// ---------------------------------------------------------------------------
31	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
32	// ---------------------------------------------------------------------------
33	
34	export const ERROR_CODES = Object.freeze({
35	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
36	  PERMISSION_DENIED: 'PERMISSION_DENIED',
37	  PROOF_INVALID: 'PROOF_INVALID',
38	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
39	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
40	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
41	  POLICY_INVALID: 'POLICY_INVALID',
42	  POLICY_VIOLATION: 'POLICY_VIOLATION',
43	  SYMLINK_INVALID: 'SYMLINK_INVALID',
44	  USAGE_ERROR: 'USAGE_ERROR',
45	});
46	
47	class ProvError extends Error {
48	  constructor(code, message, details) {
49	    super(message);
50	    this.name = 'ProvError';
51	    this.code = code;
52	    if (details !== undefined) this.details = details;
53	  }
54	}
55	
56	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
57	function wrapFsError(err, context) {
58	  if (err instanceof ProvError) return err;
59	  const where = context ? `${context}: ` : '';
60	  if (err && err.code === 'ENOENT') {
61	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
62	  }
63	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
64	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
65	  }
66	  return err;
67	}
68	
69	// ---------------------------------------------------------------------------
70	// 路径与摘要工具
71	// ---------------------------------------------------------------------------
72	
73	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
74	export function toPosix(relPath) {
75	  return relPath.split(sep).join('/');
76	}
77	
78	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
79	export function stableJsonStringify(value) {
80	  return JSON.stringify(sortDeep(value), null, 2);
81	}
82	
83	function sortDeep(value) {
84	  if (Array.isArray(value)) return value.map(sortDeep);
85	  if (value !== null && typeof value === 'object') {
86	    const out = {};
87	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
88	    return out;
89	  }
90	  return value;
91	}
92	
93	export function sha256Hex(data) {
94	  return createHash('sha256').update(data).digest('hex');
95	}
96	
97	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
98	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
99	export function keyFingerprint(keyObj) {
100	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
101	}
102	
103	// ---------------------------------------------------------------------------
104	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
105	// 空目录自然产生空清单；零字节文件按真实文件记录。
106	// 符号链接安全规则（按真实路径判定）：
107	//   - 目标越出产物根目录                 -> SYMLINK_INVALID / outside-root；
108	//   - 目标为当前递归祖先链上的目录（含根目录自身），或链接互相成环（ELOOP）
109	//                                        -> SYMLINK_INVALID / cycle；
110	//   - 指向根目录内部普通文件/目录的链接按链接路径记录目标内容；
111	//     祖先链之外的重复目标允许展开（有向无环，不会形成回路）。
112	// 判定在读取目标内容之前完成，危险链接不会被解引用读取。
113	// ---------------------------------------------------------------------------
114	
115	// 符号链接安全检查失败：携带相对路径与原因（cycle / outside-root）。
116	function symlinkError(fullPath, rootDir, reason) {
117	  const relPath = toPosix(relative(rootDir, fullPath));
118	  const message =
119	    reason === 'cycle'
120	      ? `符号链接形成回路: ${relPath}`
121	      : `符号链接越出产物根目录: ${relPath}`;
122	  return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, { path: relPath, reason });
123	}
124	
125	// 解析真实路径；底层错误按既有归类转换。
126	async function realPathOf(p, context) {
127	  try {
128	    return await realpath(p);
129	  } catch (err) {
130	    throw wrapFsError(err, context);
131	  }
132	}
133	
134	async function walkFiles(rootDir) {
135	  const found = [];
136	  const rootReal = await realPathOf(rootDir, '读取产物目录');
137	  // chain 为当前递归路径上各级目录的真实路径，用于识别指回祖先的链接回路。
138	  async function walk(dir, chain) {
139	    let entries;
140	    try {
141	      entries = await readdir(dir, { withFileTypes: true });
142	    } catch (err) {
143	      throw wrapFsError(err, '读取产物目录');
144	    }
145	    for (const entry of entries) {
146	      const full = join(dir, entry.name);
147	      if (entry.isDirectory()) {
148	        await walk(full, [...chain, await realPathOf(full, '读取产物目录')]);
149	      } else if (entry.isFile()) {
150	        found.push(full);
151	      } else if (entry.isSymbolicLink()) {
152	        // 先解析真实目标并做安全判定，再按目标类型处理：
153	        // 指向目录则继续递归，指向文件则按链接路径记录。
154	        let targetReal;
155	        try {
156	          targetReal = await realpath(full);
157	        } catch (err) {
158	          // 链接互相指向成环（如 a -> b、b -> a）时 realpath 报 ELOOP。
159	          if (err && err.code === 'ELOOP') throw symlinkError(full, rootDir, 'cycle');
160	          throw wrapFsError(err, '读取符号链接');
161	        }
162	        if (!isWithin(targetReal, rootReal)) {
163	          throw symlinkError(full, rootDir, 'outside-root');
164	        }
165	        if (chain.includes(targetReal)) {
166	          throw symlinkError(full, rootDir, 'cycle');
167	        }
168	        let target;
169	        try {
170	          target = await stat(full);
171	        } catch (err) {
172	          throw wrapFsError(err, '读取符号链接');
173	        }
174	        if (target.isDirectory()) await walk(full, [...chain, targetReal]);
175	        else if (target.isFile()) found.push(full);
176	      }
177	      // 其他特殊文件（套接字/设备等）忽略。
178	    }
179	  }
180	  await walk(rootDir, [rootReal]);
181	  return found;
182	}
183	
184	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
185	function isWithin(pathAbs, dirAbs) {
186	  const relPath = relative(dirAbs, pathAbs);
187	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
188	}
189	
190	async function fileTypeFromPath(fullPath, data) {
191	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
192	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
193	  const startsWith = (bytes) =>
194	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
195	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
196	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
197	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
198	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
199	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
200	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
201	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
202	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
203	  if (
204	    startsWith([0xef, 0xbb, 0xbf]) ||
205	    startsWith([0xff, 0xfe]) ||
206	    startsWith([0xfe, 0xff])
207	  ) {
208	    return 'text/plain';
209	  }
210	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
211	  const ext = basename(fullPath).split('.').pop();
212	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
213	}
214	
215	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
216	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
217	export async function buildSbom(artifactPath, excludeDir) {
218	  const artifactAbs = resolve(artifactPath);
219	  let artifactStat;
220	  try {
221	    artifactStat = await stat(artifactAbs);
222	  } catch (err) {
223	    throw wrapFsError(err, '读取产物');
224	  }
225	
226	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
227	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
228	
229	  let files;
230	  if (artifactStat.isDirectory()) {
231	    files = await walkFiles(artifactAbs);
232	  } else {
233	    files = [artifactAbs];
234	  }
235	
236	  const entries = [];
237	  for (const full of files) {
238	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
239	    let data;
240	    try {
241	      data = await readFile(full);
242	    } catch (err) {
243	      throw wrapFsError(err, '读取产物文件');
244	    }
245	    const relPath = toPosix(relative(rootDir, full));
246	    entries.push({
247	      path: relPath,
248	      sha256: sha256Hex(data),
249	      size: data.length,
250	      type: await fileTypeFromPath(full, data),
251	    });
252	  }
253	
254	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
255	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
256	
257	  return {
258	    schemaVersion: '1.0',
259	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
260	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
261	    files: entries,
262	  };
263	}
264	
265	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
266	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
267	export function computeArtifactDigest(sbom) {
268	  return sha256Hex(stableJsonStringify(sbom.files));
269	}
270	
271	// ---------------------------------------------------------------------------
272	// 密钥与签名（Ed25519，PEM）
273	// ---------------------------------------------------------------------------
274	
275	function readPrivateKey(keyPath) {
276	  let pem;
277	  try {
278	    pem = readFileSync(keyPath);
279	  } catch (err) {
280	    throw wrapFsError(err, '读取私钥');
281	  }
282	  let keyObj;
283	  try {
284	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
285	  } catch {
286	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
287	  }
288	  if (keyObj.asymmetricKeyType !== 'ed25519') {
289	    throw new ProvError(
290	      ERROR_CODES.KEY_NOT_FOUND,
291	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
292	    );
293	  }
294	  return keyObj;
295	}
296	
297	function readPublicKey(keyPath) {
298	  let pem;
299	  try {
300	    pem = readFileSync(keyPath);
301	  } catch (err) {
302	    throw wrapFsError(err, '读取公钥');
303	  }
304	  let keyObj;
305	  try {
306	    keyObj = createPublicKey({ key: pem, format: 'pem' });
307	  } catch {
308	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
309	  }
310	  if (keyObj.asymmetricKeyType !== 'ed25519') {
311	    throw new ProvError(
312	      ERROR_CODES.KEY_NOT_FOUND,
313	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
314	    );
315	  }
316	  return keyObj;
317	}
318	
319	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
320	function nowIso() {
321	  return new Date().toISOString();
322	}
323	
324	// ---------------------------------------------------------------------------
325	// keygen
326	// ---------------------------------------------------------------------------
327	
328	export async function keygen({ keyDir, name = 'provguard' }) {
329	  const absDir = resolve(keyDir);
330	  try {
331	    await mkdir(absDir, { recursive: true });
332	  } catch (err) {
333	    throw wrapFsError(err, '创建密钥目录');
334	  }
335	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
336	  const privPath = join(absDir, `${name}.private.pem`);
337	  const pubPath = join(absDir, `${name}.public.pem`);
338	  try {
339	    await writeFile(
340	      privPath,
341	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
342	      { mode: 0o600 },
343	    );
344	    await writeFile(
345	      pubPath,
346	      publicKey.export({ type: 'spki', format: 'pem' }),
347	      { mode: 0o644 },
348	    );
349	  } catch (err) {
350	    throw wrapFsError(err, '写入密钥');
351	  }
352	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
353	}
354	
355	// ---------------------------------------------------------------------------
356	// generate
357	// ---------------------------------------------------------------------------
358	
359	export async function generate({ artifact, key, out, coKeys = [] }) {
360	  // 输入检查：产物与私钥必须存在且可读。
361	  const artifactAbs = resolve(artifact);
362	  const keyAbs = resolve(key);
363	  const coSign = coKeys.length > 0;
364	  const coKeyAbsList = coKeys.map((p) => resolve(p));
365	  const inputs = [
366	    [artifactAbs, '产物'],
367	    [keyAbs, '私钥'],
368	  ];
369	  for (const p of coKeyAbsList) inputs.push([p, '共签私钥']);
370	  for (const [p, label] of inputs) {
371	    try {
372	      await access(p, fsConstants.R_OK);
373	    } catch (err) {
374	      throw wrapFsError(err, `读取${label}`);
375	    }
376	  }
377	
378	  const outAbs = resolve(out);
379	  const parent = dirname(outAbs);
380	  try {
381	    await mkdir(parent, { recursive: true });
382	  } catch (err) {
383	    throw wrapFsError(err, '创建输出目录');
384	  }
385	
386	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
387	  try {
388	    await mkdir(outAbs, { recursive: true });
389	  } catch (err) {
390	    throw wrapFsError(err, '创建输出目录');
391	  }
392	  let outReal;
393	  try {
394	    outReal = await realpath(outAbs);
395	  } catch (err) {
396	    throw wrapFsError(err, '解析输出目录');
397	  }
398	
399	  const privateKey = readPrivateKey(keyAbs);
400	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
401	  const signingPublicKey = createPublicKey(privateKey);
402	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
403	
404	  // 共签私钥：逐一读取并校验为 Ed25519；指纹不得重复，也不得与主签名密钥相同，
405	  // 否则为 USAGE_ERROR。共签者按指纹升序排列，保证输出确定。
406	  const coSigners = [];
407	  if (coSign) {
408	    const seen = new Set([signerKeyFingerprint.toLowerCase()]);
409	    for (const p of coKeyAbsList) {
410	      const coKey = readPrivateKey(p);
411	      const fingerprint = keyFingerprint(createPublicKey(coKey));
412	      if (seen.has(fingerprint.toLowerCase())) {
413	        throw new ProvError(
414	          ERROR_CODES.USAGE_ERROR,
415	          '共签私钥重复或与主密钥相同（--co-key 必须互不相同且不同于 --key）',
416	        );
417	      }
418	      seen.add(fingerprint.toLowerCase());
419	      coSigners.push({ key: coKey, fingerprint });
420	    }
421	    coSigners.sort((a, b) => (a.fingerprint < b.fingerprint ? -1 : a.fingerprint > b.fingerprint ? 1 : 0));
422	  }
423	
424	  const sbom = await buildSbom(artifactAbs, outReal);
425	  const artifactDigest = computeArtifactDigest(sbom);
426	
427	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
428	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
429	  const sbomCanonical = stableJsonStringify(sbom);
430	  const sbomDigest = sha256Hex(sbomCanonical);
431	
432	  const proof = {
433	    proofVersion: coSign ? PROOF_VERSION_COSIGN : PROOF_VERSION,
434	    artifactName: basename(artifactAbs),
435	    artifactDigest,
436	    fileName: basename(artifactAbs),
437	    size: sbom.files.reduce((n, f) => n + f.size, 0),
438	    generatedAt: nowIso(),
439	    signerKeyFingerprint,
440	    sbomDigest,
441	    files: sbom.files,
442	  };
443	  // 启用共签时证明声明共签者集合（按指纹升序、已去重），随证明一起被主签名保护。
444	  if (coSign) {
445	    proof.cosignerKeyFingerprints = coSigners.map((c) => c.fingerprint);
446	  }
447	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
448	  const proofJson = stableJsonStringify(proof) + '\n';
449	  const sbomJson = sbomCanonical + '\n';
450	
451	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
452	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
453	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
454	  const signatureB64 = signature.toString('base64') + '\n';
455	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
456	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
457	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
458	
459	  const proofPath = join(outReal, 'proof.json');
460	  const sbomPath = join(outReal, 'sbom.json');
461	  const sigPath = join(outReal, 'proof.json.sig');
462	  const sbomSigPath = join(outReal, 'sbom.json.sig');
463	  // 共签清单：每个共签者对与主签名相同的证明规范字节签名（proof.cosignatures.json），
464	  // 并另对 SBOM 规范字节签名（sbom.cosignatures.json）。不提供 --co-key 时不创建这些文件。
465	  const proofCosigPath = coSign ? join(outReal, 'proof.cosignatures.json') : null;
466	  const sbomCosigPath = coSign ? join(outReal, 'sbom.cosignatures.json') : null;
467	  try {
468	    await atomicWrite(proofPath, proofJson);
469	    await atomicWrite(sbomPath, sbomJson);
470	    await atomicWrite(sigPath, signatureB64);
471	    await atomicWrite(sbomSigPath, sbomSignatureB64);
472	    if (coSign) {
473	      const proofBytes = Buffer.from(proofJson.trimEnd(), 'utf8');
474	      const sbomBytes = Buffer.from(sbomCanonical, 'utf8');
475	      const cosignManifest = (bytes) => ({
476	        schemaVersion: COSIGN_SCHEMA_VERSION,
477	        artifactDigest,
478	        sbomDigest,
479	        signers: coSigners.map((c) => ({
480	          keyFingerprint: c.fingerprint,
481	          signature: cryptoSign(null, bytes, c.key).toString('base64'),
482	        })),
483	      });
484	      await atomicWrite(proofCosigPath, stableJsonStringify(cosignManifest(proofBytes)) + '\n');
485	      await atomicWrite(sbomCosigPath, stableJsonStringify(cosignManifest(sbomBytes)) + '\n');
486	    }
487	  } catch (err) {
488	    throw wrapFsError(err, '写入证明产物');
489	  }
490	
491	  const result = {
492	    proofPath,
493	    sbomPath,
494	    signaturePath: sigPath,
495	    sbomSignaturePath: sbomSigPath,
496	    artifactDigest,
497	    sbomDigest,
498	    fileCount: sbom.files.length,
499	    proofVersion: proof.proofVersion,
500	  };
501	  if (coSign) {
502	    result.cosignerCount = coSigners.length;
503	    result.proofCosignaturesPath = proofCosigPath;
504	    result.sbomCosignaturesPath = sbomCosigPath;
505	  }
506	  return result;
507	}
