509	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
510	async function atomicWrite(target, contents) {
511	  const dir = dirname(target);
512	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
513	  await writeFile(tmp, contents, { mode: 0o644 });
514	  try {
515	    await rename(tmp, target);
516	  } catch (err) {
517	    await rm(tmp, { force: true });
518	    throw err;
519	  }
520	}
