526	export async function verify({
527	  artifact,
528	  proof: proofPath,
529	  signature: sigPath,
530	  key: pubKeyPath,
531	  sbom: sbomPath,
532	  sbomSignature: sbomSigPath,
533	  policy: policyPath,
534	  cosignatures: cosigDir,
535	  cosignerKeys,
536	  minCosigners,
537	}) {
538	  const artifactAbs = resolve(artifact);
539	  const proofAbs = resolve(proofPath);
540	  const sigAbs = resolve(sigPath);
541	  const keyAbs = resolve(pubKeyPath);
542	
543	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
544	  const sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
545	  if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
546	    throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
547	  }
548	  const sbomAbs = sbomMode ? resolve(sbomPath) : null;
549	  const sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
550	
551	  // 共签校验三参数必须同时提供：--cosignatures、--cosigner-key（可重复）、--min-cosigners。
552	  const cosignMode =
553	    cosigDir !== undefined || cosignerKeys !== undefined || minCosigners !== undefined;
554	  if (cosignMode && (cosigDir === undefined || cosignerKeys === undefined || minCosigners === undefined)) {
555	    throw new ProvError(
556	      ERROR_CODES.USAGE_ERROR,
557	      '--cosignatures、--cosigner-key 与 --min-cosigners 必须同时提供',
558	    );
559	  }
560	  const cosignerKeyList = cosignMode
561	    ? (Array.isArray(cosignerKeys) ? cosignerKeys : [cosignerKeys])
562	    : [];
563	
564	  // 1) 所有输入必须存在且可读。
565	  const inputs = [
566	    [artifactAbs, '产物'],
567	    [proofAbs, '证明文件'],
568	    [sigAbs, '签名文件'],
569	    [keyAbs, '公钥'],
570	  ];
571	  if (sbomMode) {
572	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
573	  }
574	  for (const [p, label] of inputs) {
575	    try {
576	      await access(p, fsConstants.R_OK);
577	    } catch (err) {
578	      throw wrapFsError(err, `读取${label}`);
579	    }
580	  }
581	
582	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
583	  const publicKey = readPublicKey(keyAbs);
584	
585	  // 3) 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
586	  let proofText;
587	  try {
588	    proofText = await readFileUtf8(proofAbs);
589	  } catch (err) {
590	    throw wrapFsError(err, '读取证明文件');
591	  }
592	  let proof;
593	  try {
594	    proof = JSON.parse(proofText);
595	  } catch {
596	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
597	  }
598	  const proofError = validateProof(proof);
599	  if (proofError) {
600	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
601	  }
602	
603	  // 4) 签名文件必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
604	  const sigText = await readFileUtf8(sigAbs);
605	  const sigB64 = sigText.replace(/\s+/g, '');
606	  let sigBuf;
607	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
608	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
609	  }
610	  try {
611	    sigBuf = Buffer.from(sigB64, 'base64');
612	  } catch {
613	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
614	  }
615	  if (sigBuf.length !== 64) {
616	    throw new ProvError(
617	      ERROR_CODES.PROOF_INVALID,
618	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
619	    );
620	  }
621	
622	  // 5) 重算证明的规范字节并验签。
623	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
624	  //    generate 写出的即为稳定规范形式，因此往返一致。
625	  //
626	  //    错误归类（三者互不相同）：
627	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
628	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
629	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
630	  const providedFingerprint = keyFingerprint(publicKey);
631	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
632	    throw new ProvError(
633	      ERROR_CODES.KEY_NOT_FOUND,
634	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
635	      {
636	        providedKeyFingerprint: providedFingerprint,
637	        proofKeyFingerprint: proof.signerKeyFingerprint,
638	      },
639	    );
640	  }
641	
642	  const canonicalProof = stableJsonStringify(proof);
643	  let sigOk = false;
644	  try {
645	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
646	  } catch {
647	    sigOk = false;
648	  }
649	  if (!sigOk) {
650	    throw new ProvError(
651	      ERROR_CODES.SIGNATURE_INVALID,
652	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
653	    );
654	  }
655	
656	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
657	  //    排除输出目录：证明/签名/清单通常与产物相邻，验证时不得把它们计入产物。
658	  const excludeDir = inferExcludeDir(proofAbs, artifactAbs);
659	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
660	  const currentDigest = computeArtifactDigest(currentSbom);
661	
662	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
663	  if (mismatches.length > 0) {
664	    throw new ProvError(
665	      ERROR_CODES.INTEGRITY_MISMATCH,
666	      `检测到 ${mismatches.length} 处完整性差异`,
667	      { mismatches },
668	    );
669	  }
670	
671	  // 7) SBOM 模式：校验 sbom.json 结构、proof.sbomDigest、SBOM 签名，
672	  //    并确认 SBOM 清单与证明清单（进而与当前扫描）逐项一致。
673	  let sbomDigest;
674	  if (sbomMode) {
675	    sbomDigest = await verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey });
676	  }
677	
678	  // 8) 共签模式：在证明、可选 SBOM 与产物完整性全部通过后，校验共签清单与各共签签名。
679	  let cosignerCount;
680	  if (cosignMode) {
681	    cosignerCount = await verifyCosignatures({
682	      cosigDir,
683	      cosignerKeyPaths: cosignerKeyList,
684	      minCosigners,
685	      proof,
686	      canonicalProof,
687	      currentSbom,
688	    });
689	  }
690	
691	  // 9) 可选策略：仅在签名、完整性、可选 SBOM、可选共签校验全部通过后加载并执行。
692	  //    策略文件自身缺失/不可读/非法按其错误码返回（INPUT_NOT_FOUND /
693	  //    PERMISSION_DENIED / POLICY_INVALID）；内容违规为 POLICY_VIOLATION。
694	  let policyStatus;
695	  if (policyPath !== undefined) {
696	    const policy = await loadPolicy(policyPath);
697	    const violations = evaluatePolicy(policy, proof, sbomMode);
698	    if (violations.length > 0) {
699	      throw new ProvError(
700	        ERROR_CODES.POLICY_VIOLATION,
701	        `策略校验未通过（${violations.length} 项违规）`,
702	        { violations },
703	      );
704	    }
705	    policyStatus = 'PASS';
706	  }
707	
708	  const result = {
709	    status: 'VERIFIED',
710	    proofVersion: proof.proofVersion,
711	    artifactDigest: currentDigest,
712	    fileCount: currentSbom.files.length,
713	  };
714	  if (sbomMode) result.sbomDigest = sbomDigest;
715	  if (cosignMode) result.cosignerCount = cosignerCount;
716	  if (policyPath !== undefined) result.policyStatus = policyStatus;
717	  return result;
718	}
