720	// SBOM 校验：结构 -> 摘要 -> 签名 -> 清单一致性。
721	async function verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey }) {
722	  // a) sbom.json 必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
723	  const sbomText = await readFileUtf8(sbomAbs);
724	  let sbom;
725	  try {
726	    sbom = JSON.parse(sbomText);
727	  } catch {
728	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 文件不是合法的 JSON');
729	  }
730	  const sbomError = validateSbom(sbom);
731	  if (sbomError) {
732	    throw new ProvError(ERROR_CODES.PROOF_INVALID, sbomError);
733	  }
734	
735	  // b) 证明必须携带合法的 sbomDigest 字段。
736	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
737	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
738	  }
739	
740	  // c) 重算 SBOM 规范字节摘要并与证明比对 —— 不一致说明 sbom.json 被替换或改动。
741	  const canonicalSbom = stableJsonStringify(sbom);
742	  const recomputed = sha256Hex(canonicalSbom);
743	  if (recomputed.toLowerCase() !== proof.sbomDigest.toLowerCase()) {
744	    throw new ProvError(
745	      ERROR_CODES.INTEGRITY_MISMATCH,
746	      'sbom.json 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
747	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
748	    );
749	  }
750	
751	  // d) SBOM 签名：合法 Base64 且 64 字节 —— 否则 PROOF_INVALID；验签失败 SIGNATURE_INVALID。
752	  const sigText = await readFileUtf8(sbomSigAbs);
753	  const sigB64 = sigText.replace(/\s+/g, '');
754	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
755	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 签名文件不是合法的 Base64 内容');
756	  }
757	  const sigBuf = Buffer.from(sigB64, 'base64');
758	  if (sigBuf.length !== 64) {
759	    throw new ProvError(
760	      ERROR_CODES.PROOF_INVALID,
761	      `SBOM 签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
762	    );
763	  }
764	  let sigOk = false;
765	  try {
766	    sigOk = cryptoVerify(null, Buffer.from(canonicalSbom, 'utf8'), publicKey, sigBuf);
767	  } catch {
768	    sigOk = false;
769	  }
770	  if (!sigOk) {
771	    throw new ProvError(
772	      ERROR_CODES.SIGNATURE_INVALID,
773	      'SBOM 签名与 sbom.json 内容不匹配（SBOM 可能被改动，或签名已损坏）',
774	    );
775	  }
776	
777	  // e) SBOM 清单与证明清单逐项一致（证明与当前扫描已在前面比对，故三方一致）。
778	  const mismatches = diffSbomAgainstProof(sbom, proof);
779	  if (mismatches.length > 0) {
780	    throw new ProvError(
781	      ERROR_CODES.INTEGRITY_MISMATCH,
782	      `SBOM 与证明清单存在 ${mismatches.length} 处差异`,
783	      { mismatches },
784	    );
785	  }
786	
787	  return recomputed;
788	}
789	
790	// ---------------------------------------------------------------------------
791	// 共签校验（proof.cosignatures.json / sbom.cosignatures.json）
792	// ---------------------------------------------------------------------------
793	
794	// 在证明、可选 SBOM 与产物完整性全部通过后调用。
795	// 校验顺序：清单可读性 -> 结构与绑定（PROOF_INVALID）-> SBOM 摘要复算
796	// （INTEGRITY_MISMATCH）-> 共签公钥归属（KEY_NOT_FOUND）-> 逐签名验签与
797	// 有效数量（SIGNATURE_INVALID）。返回有效共签者数量（按指纹去重）。
798	async function verifyCosignatures({ cosigDir, cosignerKeyPaths, minCosigners, proof, canonicalProof, currentSbom }) {
799	  const dir = resolve(cosigDir);
800	  const proofManifestAbs = join(dir, 'proof.cosignatures.json');
801	  const sbomManifestAbs = join(dir, 'sbom.cosignatures.json');
802	  for (const [p, label] of [
803	    [proofManifestAbs, '证明共签清单'],
804	    [sbomManifestAbs, 'SBOM 共签清单'],
805	  ]) {
806	    try {
807	      await access(p, fsConstants.R_OK);
808	    } catch (err) {
809	      throw wrapFsError(err, `读取${label}`);
810	    }
811	  }
812	  const proofManifest = await readCosignManifest(proofManifestAbs, '证明共签清单');
813	  const sbomManifest = await readCosignManifest(sbomManifestAbs, 'SBOM 共签清单');
814	
815	  // 清单必须绑定当前证明：记录的产物/SBOM 摘要与证明一致。
816	  for (const [m, label] of [
817	    [proofManifest, '证明共签清单'],
818	    [sbomManifest, 'SBOM 共签清单'],
819	  ]) {
820	    if (
821	      m.artifactDigest.toLowerCase() !== proof.artifactDigest.toLowerCase() ||
822	      m.sbomDigest.toLowerCase() !== proof.sbomDigest.toLowerCase()
823	    ) {
824	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `${label}与证明记录的摘要不一致`);
825	    }
826	  }
827	
828	  // 清单签名者集合必须与证明声明的共签者集合一致，且不得包含主签名指纹。
829	  const declared = Array.isArray(proof.cosignerKeyFingerprints)
830	    ? proof.cosignerKeyFingerprints.map((fp) => fp.toLowerCase())
831	    : [];
832	  const mainFingerprint = proof.signerKeyFingerprint.toLowerCase();
833	  for (const [m, label] of [
834	    [proofManifest, '证明共签清单'],
835	    [sbomManifest, 'SBOM 共签清单'],
836	  ]) {
837	    const manifestSet = m.signers.map((s) => s.keyFingerprint.toLowerCase());
838	    if (manifestSet.includes(mainFingerprint)) {
839	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `${label}不得包含主签名密钥指纹`);
840	    }
841	    const sameSet =
842	      manifestSet.length === declared.length &&
843	      manifestSet.every((fp, i) => fp === declared[i]);
844	    if (!sameSet) {
845	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `${label}签名者集合与证明声明的共签者不一致`);
846	    }
847	  }
848	
849	  // 复算当前 SBOM 规范字节摘要并与证明比对 —— SBOM 变化优先报 INTEGRITY_MISMATCH。
850	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
851	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
852	  }
853	  const canonicalSbom = stableJsonStringify(currentSbom);
854	  if (sha256Hex(canonicalSbom).toLowerCase() !== proof.sbomDigest.toLowerCase()) {
855	    throw new ProvError(
856	      ERROR_CODES.INTEGRITY_MISMATCH,
857	      'SBOM 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
858	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
859	    );
860	  }
861	
862	  // 逐一校验提供的共签公钥：必须是证明声明的共签者，且其对证明与 SBOM 的签名均有效。
863	  const verified = new Set();
864	  for (const keyPath of cosignerKeyPaths) {
865	    const pub = readPublicKey(resolve(keyPath));
866	    const fp = keyFingerprint(pub).toLowerCase();
867	    if (!declared.includes(fp)) {
868	      throw new ProvError(
869	        ERROR_CODES.KEY_NOT_FOUND,
870	        '共签公钥未在证明声明的共签者集合中（未声明或错误公钥）',
871	        { providedKeyFingerprint: fp },
872	      );
873	    }
874	    const proofEntry = proofManifest.signers.find((s) => s.keyFingerprint.toLowerCase() === fp);
875	    const sbomEntry = sbomManifest.signers.find((s) => s.keyFingerprint.toLowerCase() === fp);
876	    const proofSigOk = verifyCosigSignature(proofEntry.signature, canonicalProof, pub);
877	    const sbomSigOk = verifyCosigSignature(sbomEntry.signature, canonicalSbom, pub);
878	    if (!proofSigOk || !sbomSigOk) {
879	      throw new ProvError(
880	        ERROR_CODES.SIGNATURE_INVALID,
881	        `共签签名与内容不匹配（指纹 ${fp}，${proofSigOk ? 'SBOM' : '证明'}签名失配）`,
882	      );
883	    }
884	    verified.add(fp);
885	  }
886	
887	  if (verified.size < minCosigners) {
888	    throw new ProvError(
889	      ERROR_CODES.SIGNATURE_INVALID,
890	      `有效共签数量不足：需要至少 ${minCosigners} 个，实际 ${verified.size} 个`,
891	    );
892	  }
893	  return verified.size;
894	}
895	
896	function verifyCosigSignature(signatureB64, canonicalBytes, publicKey) {
897	  try {
898	    return cryptoVerify(
899	      null,
900	      Buffer.from(canonicalBytes, 'utf8'),
901	      publicKey,
902	      Buffer.from(signatureB64.replace(/\s+/g, ''), 'base64'),
903	    );
904	  } catch {
905	    return false;
906	  }
907	}
908	
909	async function readCosignManifest(path, label) {
910	  const text = await readFileUtf8(path);
911	  let manifest;
912	  try {
913	    manifest = JSON.parse(text);
914	  } catch {
915	    throw new ProvError(ERROR_CODES.PROOF_INVALID, `${label}不是合法的 JSON`);
916	  }
917	  const error = validateCosignManifest(manifest);
918	  if (error) {
919	    throw new ProvError(ERROR_CODES.PROOF_INVALID, `${label}${error}`);
920	  }
921	  return manifest;
922	}
923	
924	// 共签清单结构校验：schemaVersion、摘要字段、按指纹严格升序（隐含去重）的 signers，
925	// 每项含合法指纹与可解码为 64 字节的 Base64 Ed25519 签名。
926	function validateCosignManifest(manifest) {
927	  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) {
928	    return '顶层必须是 JSON 对象';
929	  }
930	  if (manifest.schemaVersion !== COSIGN_SCHEMA_VERSION) {
931	    return `schemaVersion 缺失或不受支持（应为 ${COSIGN_SCHEMA_VERSION}）`;
932	  }
933	  for (const k of ['artifactDigest', 'sbomDigest']) {
934	    if (typeof manifest[k] !== 'string' || !/^[0-9a-f]{64}$/i.test(manifest[k])) {
935	      return `字段缺失或类型非法: ${k}`;
936	    }
937	  }
938	  if (!Array.isArray(manifest.signers)) return '字段缺失或类型非法: signers';
939	  let prev = null;
