477	function writePolicy(obj, name = 'policy.json') {
478	  const p = join(root, name);
479	  writeFileSync(p, JSON.stringify(obj, null, 2));
480	  return p;
481	}
482	
483	function verifyWithPolicy(pub, policyPath, { sbom = false, overrides = {} } = {}) {
484	  const args = [
485	    'verify',
486	    '--artifact', overrides.artifact ?? paths.art,
487	    '--proof', overrides.proof ?? join(paths.out, 'proof.json'),
488	    '--signature', overrides.signature ?? join(paths.out, 'proof.json.sig'),
489	    '--key', overrides.key ?? pub,
490	  ];
491	  if (sbom) {
492	    args.push('--sbom', overrides.sbom ?? join(paths.out, 'sbom.json'));
493	    args.push('--sbom-signature', overrides.sbomSignature ?? join(paths.out, 'sbom.json.sig'));
494	  }
495	  args.push('--policy', policyPath);
496	  return run(args);
497	}
498	
499	function readProof() {
500	  return JSON.parse(readFileSync(join(paths.out, 'proof.json'), 'utf8'));
501	}
502	
503	// 用私钥对（可能被改动的）证明重新签名，使签名与完整性步骤通过，
504	// 从而专门测试策略层对非法 generatedAt 的处理。
505	function resignProof(proofObj, privPath) {
506	  const key = createPrivateKey(readFileSync(privPath));
507	  const canonical = stableJsonStringify(proofObj);
508	  writeFileSync(join(paths.out, 'proof.json'), `${canonical}\n`);
509	  writeFileSync(
510	    join(paths.out, 'proof.json.sig'),
511	    `${cryptoSign(null, Buffer.from(canonical, 'utf8'), key).toString('base64')}\n`,
512	  );
513	}
